const hi = Math.floor(nominal / 65536);
const lo = nominal & 0xFFFF;
const common = {logicalSilo:Number(silo),calibrationSilo:silo,requestPurpose:'calibration',calibrationMode:'known-weight'};
return [[
 {...common,modbusAction:'write',calibrationAction:`Silo ${silo}: password unlocked for known load`,payload:{value:21930,fc:6,unitid:1,address:49,quantity:1}},
 {...common,modbusAction:'write',calibrationAction:`Silo ${silo}: known load sampled`,payload:{value:[32767,65535],fc:16,unitid:1,address:18,quantity:2}},
 {...common,modbusAction:'write',calibrationAction:`Silo ${silo}: password unlocked for NOV`,payload:{value:21930,fc:6,unitid:1,address:49,quantity:1}},
 {...common,modbusAction:'write',calibrationAction:`Silo ${silo}: nominal value ${kg} kg written`,payload:{value:[hi,lo],fc:16,unitid:1,address:20,quantity:2}},
 {...common,modbusAction:'write',calibrationAction:`Silo ${silo}: calibration saved`,calibrationLast:true,payload:{value:1,fc:6,unitid:1,address:48,quantity:1}}
],{requestPurpose:'calibration',calibrationSilo:silo,payload:`✓ Known-load sequence queued for logical Silo ${silo}: ${kg} kg. Keep the load stable until save is confirmed.`}];

const silo = Number(msg.logicalSilo);
const unitid = silo === 1 ? Number(flow.get('ads301Silo1UnitId')) : Number(flow.get('ads301Silo2UnitId'));
if (![1,2].includes(silo) || !Number.isInteger(unitid) || unitid < 1 || unitid > 96) {
  flow.set('ads301BusBusy', false);
  msg.payload = `No valid Modbus Unit ID mapped for logical Silo ${silo}.`;
  return [null,msg];
}
msg.payload.unitid = unitid;
msg.unitid = unitid;
msg.ads301UnitId = unitid;
return [msg,null];

if (flow.get('ads301BusBusy')) return null;
const silo = Number(msg.logicalSilo);
const unitid = silo === 1 ? Number(flow.get('ads301Silo1UnitId')) : Number(flow.get('ads301Silo2UnitId'));
if (![1,2].includes(silo) || !Number.isInteger(unitid) || unitid < 1 || unitid > 96) return null;
msg.requestPurpose = 'telemetry';
msg.ads301UnitId = unitid;
msg.payload = {fc:3,unitid,address:40,quantity:2};
return msg;

const raw = msg.payload?.data ?? msg.payload;
if (!Array.isArray(raw) || raw.length < 2) return null;
const silo = Number(msg.logicalSilo);
if (![1,2].includes(silo)) return null;
const high = Number(raw[0]) & 0xFFFF;
const low = Number(raw[1]) & 0xFFFF;
let value = (high * 0x10000) + low;
if (value >= 0x80000000) value -= 0x100000000;
const unitsPerKg = Number(env.get('ADS301_UNITS_PER_KG') || 1);
if (!Number.isFinite(unitsPerKg) || unitsPerKg <= 0) return null;
const gatewayId = env.get('GATEWAY_SERIAL') || 'UNKNOWN_GW';
const siloId = String(silo).padStart(2,'0');
const deviceSerialNumber = `${gatewayId}_silo_${siloId}`;
msg.payload = {
  gateway_id: gatewayId,
  device_serial_number: deviceSerialNumber,
  sensor_type: 'silo_weight',
  timestamp: new Date().toISOString().replace(/\.\d{3}Z$/,'Z'),
  data: {weight_kg: value / unitsPerKg}
};
msg.topic = `gateway/${gatewayId}/silo/${deviceSerialNumber}/telemetry`;
return msg;

const text = typeof msg.payload === 'string'
    ? msg.payload
    : JSON.stringify(msg.payload ?? '');

msg.payload = text;

const lower = text.toLowerCase();
const isError = text.startsWith('✗') ||
    /failed|invalid|cannot|do not continue|not set|must be|already running/.test(lower);

const isAddress = msg.requestPurpose === 'addressing' ||
    msg.requestPurpose === 'verify-address' ||
    msg.addressTargetSilo !== undefined ||
    /address|mapping|modbus unit|shared bus mapping/.test(lower);

const isCalibration = msg.requestPurpose === 'calibration' ||
    msg.calibrationMode !== undefined ||
    msg.calibrationSilo !== undefined ||
    /calibration|zero|known test weight|known-load/.test(lower);

const significant = isError ||
    /applied|queued|verified|sequence complete|recorded|saved/.test(lower);

const toast = significant ? {
    ...msg,
    topic: isError ? 'ADS301 error' : 'ADS301 update',
    payload: text
} : null;

return [
    isAddress ? {...msg} : null,
    isCalibration ? {...msg} : null,
    {...msg},
    toast
];

// ── FAI Gateway Parser v9.0 — Individual Weight Events ──────────────────────
//
// Arduino input:
//   One 50-byte LoRaWAN packet every approximately 3 minutes.
//
//   Byte 0:       protocol version
//   Byte 1:       number of weight samples
//   Bytes 2-3:    batch number, UInt16 LE
//   Bytes 4-39:   18 × weight readings, UInt16 LE
//   Bytes 40-41:  temperature × 100, Int16 LE
//   Bytes 42-43:  CO2 ppm, UInt16 LE
//   Bytes 44-45:  light lux, UInt16 LE
//   Bytes 46-47:  humidity × 100, UInt16 LE
//   Bytes 48-49:  pressure × 10, UInt16 LE
//
// Weight behaviour:
//   - The 18 Arduino readings are genuine spot readings taken 10 seconds apart.
//   - Each valid reading becomes a separate backend Type 0x02 event.
//   - Each Type 0x02 event contains the one weight repeated across all 50
//     legacy array positions.
//   - The 18 backend event timestamps are reconstructed at 10-second intervals.
//   - 0xFFFF means invalid and that specific event is omitted.
//   - Genuine 0 g readings are retained.
//
// Backend output:
//   Type 0x01: environmental packet, 58 bytes, signature 013a.
//   Type 0x02: weight packet, 106 bytes, signature 026a.
//
// There is no longer a cross-message weight queue.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const TARGET_CLOUD_SID = 16777216;

const EXPECTED_PAYLOAD_LENGTH = 50;
const EXPECTED_VERSION = 1;

const MAX_WEIGHT_SAMPLES = 18;
const WEIGHT_INTERVAL_MS = 10000;

const INVALID_WEIGHT = 0xFFFF;

// Retain a small duplicate history for each device.
const RECENT_MESSAGE_HISTORY = 64;
const STATE_NAMESPACE = "faiParserV90";

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn(
        "Invalid ChirpStack message: required payload fields are missing"
    );

    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(msg.payload.deviceInfo.devEui).toUpperCase();

const uidHex =
    devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(`Invalid DevEUI: ${devEui}`);
    return null;
}

const dynamicUid =
    parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(
        `Unable to calculate UID from DevEUI: ${devEui}`
    );

    return null;
}

// ============================================================================
// Decode compact LoRaWAN payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length !== EXPECTED_PAYLOAD_LENGTH) {
    node.warn(
        `Unexpected payload length from ${devEui}: ` +
        `${buf.length} bytes; expected ${EXPECTED_PAYLOAD_LENGTH}`
    );

    return null;
}

// ============================================================================
// Decode header
// ============================================================================

const protocolVersion =
    buf.readUInt8(0);

const sampleCount =
    buf.readUInt8(1);

const batchNumber =
    buf.readUInt16LE(2);

if (protocolVersion !== EXPECTED_VERSION) {
    node.warn(
        `Unsupported payload version from ${devEui}: ` +
        `${protocolVersion}; expected ${EXPECTED_VERSION}`
    );

    return null;
}

if (
    sampleCount === 0 ||
    sampleCount > MAX_WEIGHT_SAMPLES
) {
    node.warn(
        `Invalid weight sample count from ${devEui}: ` +
        sampleCount
    );

    return null;
}

if (sampleCount !== MAX_WEIGHT_SAMPLES) {
    node.warn(
        `Partial weight batch from ${devEui}: ` +
        `${sampleCount}/${MAX_WEIGHT_SAMPLES}`
    );
}

// ============================================================================
// Duplicate uplink protection
// ============================================================================
//
// Prefer ChirpStack's frame counter when available. Otherwise use the complete
// compact payload and Arduino batch number.

const recentMessagesKey =
    `${STATE_NAMESPACE}_recent_${devEui}`;

let recentMessages =
    global.get(recentMessagesKey);

if (!Array.isArray(recentMessages)) {
    recentMessages = [];
}

const frameCounter =
    Number(msg.payload.fCnt);

const messageSignature =
    Number.isInteger(frameCounter)
        ? `fcnt:${frameCounter}`
        : `batch:${batchNumber}:${buf.toString("hex")}`;

if (recentMessages.includes(messageSignature)) {
    node.warn(
        `Ignoring duplicate LoRa batch ${batchNumber} ` +
        `from ${devEui}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate batch ${batchNumber}`
    });

    return null;
}

recentMessages.push(messageSignature);

if (recentMessages.length > RECENT_MESSAGE_HISTORY) {
    recentMessages =
        recentMessages.slice(-RECENT_MESSAGE_HISTORY);
}

global.set(
    recentMessagesKey,
    recentMessages
);

// ============================================================================
// Decode environmental data
// ============================================================================

const temp =
    buf.readInt16LE(40) / 100.0;

const co2 =
    buf.readUInt16LE(42);

const lux =
    buf.readUInt16LE(44);

const humidity =
    buf.readUInt16LE(46) / 100.0;

const pressure =
    buf.readUInt16LE(48) / 10.0;

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(msg.payload.rxInfo) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(rx => Number(rx.rssi))
            .filter(value => Number.isFinite(value));

    if (validRssiValues.length > 0) {
        bestRssi =
            Math.max(...validRssiValues);
    }
}

const rawRssi =
    Math.abs(bestRssi);

// ============================================================================
// Timestamp helpers
// ============================================================================
//
// Preserve the previously proven behaviour by using Node-RED processing time
// as the time of the newest sample.
//
// For an 18-reading batch:
//
//   sample 0  = newest time minus 170 seconds
//   sample 1  = newest time minus 160 seconds
//   ...
//   sample 17 = newest time

const newestSampleTime =
    new Date();

function formatBackendTimestamp(date) {
    return (
        date.toISOString().split(".")[0] +
        "+00:00"
    );
}

// ============================================================================
// Backend message helper
// ============================================================================

const outMessages = [];

const usedPacketNumbers =
    new Set();

function nextPacketNumber() {
    let packetNumber;

    do {
        packetNumber =
            Math.floor(Math.random() * 65536);
    } while (usedPacketNumbers.has(packetNumber));

    usedPacketNumbers.add(packetNumber);

    return packetNumber;
}

function makeBackendMessage(
    hexData,
    receivedTimestamp
) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": receivedTimestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": nextPacketNumber(),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// Forge one Type 0x02 packet for each valid weight reading
//
// Type:      0x02
// Length:    106 bytes
// Signature: 026a
// ============================================================================

let validWeightEvents = 0;
let invalidWeightEvents = 0;
let genuineZeroEvents = 0;

let firstValidWeight = null;
let lastValidWeight = null;

let firstWeightTimestamp = null;
let lastWeightTimestamp = null;

for (let i = 0; i < sampleCount; i++) {
    const weight =
        buf.readUInt16LE(4 + (i * 2));

    const ageFromNewestMs =
        (sampleCount - 1 - i) *
        WEIGHT_INTERVAL_MS;

    const sampleTime =
        new Date(
            newestSampleTime.getTime() -
            ageFromNewestMs
        );

    const sampleTimestamp =
        formatBackendTimestamp(sampleTime);

    if (weight === INVALID_WEIGHT) {
        invalidWeightEvents++;

        node.warn(
            `Skipping invalid weight — ` +
            `device=${devEui}, ` +
            `batch=${batchNumber}, ` +
            `sample=${i + 1}/${sampleCount}, ` +
            `timestamp=${sampleTimestamp}`
        );

        continue;
    }

    // Preserve genuine zeroes and reserve 0xFFFF for invalid readings.
    const outputWeight =
        Math.min(
            65534,
            Math.max(
                0,
                Math.round(weight)
            )
        );

    if (outputWeight === 0) {
        genuineZeroEvents++;
    }

    const wBuf =
        Buffer.alloc(106, 0);

    wBuf.writeUInt8(0x02, 0);
    wBuf.writeUInt8(0x6A, 1);

    // Bytes 2-5 remain reserved and zero-filled.
    //
    // Repeat this single spot reading across the fixed legacy 50-value
    // structure. The backend associates the complete telegram with the
    // timestamp above.

    for (let j = 0; j < 50; j++) {
        wBuf.writeUInt16LE(
            outputWeight,
            6 + (j * 2)
        );
    }

    outMessages.push(
        makeBackendMessage(
            wBuf.toString("hex"),
            sampleTimestamp
        )
    );

    if (firstValidWeight === null) {
        firstValidWeight =
            outputWeight;

        firstWeightTimestamp =
            sampleTimestamp;
    }

    lastValidWeight =
        outputWeight;

    lastWeightTimestamp =
        sampleTimestamp;

    validWeightEvents++;
}

// ============================================================================
// Forge Type 0x01 environmental packet
//
// Type:      0x01
// Length:    58 bytes
// Signature: 013a
// ============================================================================

const envBuf =
    Buffer.alloc(58, 0);

envBuf.writeUInt8(0x01, 0);
envBuf.writeUInt8(0x3A, 1);

// Bytes 2-5 remain reserved and zero-filled.

envBuf.writeFloatLE(
    temp,
    6
);                                      // AirTemperature

envBuf.writeFloatLE(
    pressure,
    10
);                                      // AirPressure

envBuf.writeFloatLE(
    temp,
    14
);                                      // HumidityTemperature

envBuf.writeFloatLE(
    humidity,
    18
);                                      // Humidity

envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(lux)
        )
    ),
    22
);                                      // LightALS

// Confirmed backend workaround:
// GASCO2 must be written as UInt32 rather than Float32.
envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(co2)
        )
    ),
    26
);                                      // GASCO2

envBuf.writeFloatLE(0.0, 30);            // GASTemperature
envBuf.writeFloatLE(0.0, 34);            // GASHumidity
envBuf.writeFloatLE(0.0, 38);            // GASNH3
envBuf.writeFloatLE(0.0, 42);            // GASCO
envBuf.writeFloatLE(0.0, 46);            // GASNO2
envBuf.writeFloatLE(temp, 50);           // BoardTemperature
envBuf.writeFloatLE(temp, 54);           // PT100Temperature

const environmentalTimestamp =
    formatBackendTimestamp(newestSampleTime);

// Add the environmental packet after the chronological weight events.
outMessages.push(
    makeBackendMessage(
        envBuf.toString("hex"),
        environmentalTimestamp
    )
);

// ============================================================================
// Diagnostics
// ============================================================================

node.warn(
    `BATCH DECODED — ` +
    `device=${devEui}, ` +
    `batch=${batchNumber}, ` +
    `samples=${sampleCount}, ` +
    `validWeights=${validWeightEvents}, ` +
    `invalidWeights=${invalidWeightEvents}, ` +
    `genuineZeros=${genuineZeroEvents}`
);

if (validWeightEvents > 0) {
    node.warn(
        `WEIGHT EVENTS CREATED — ` +
        `device=${devEui}, ` +
        `count=${validWeightEvents}, ` +
        `firstWeight=${firstValidWeight}, ` +
        `firstTime=${firstWeightTimestamp}, ` +
        `lastWeight=${lastValidWeight}, ` +
        `lastTime=${lastWeightTimestamp}`
    );
}

node.warn(
    `PARSER OUTPUT — ` +
    `device=${devEui}, ` +
    `messages=${outMessages.length}, ` +
    `weightMessages=${validWeightEvents}, ` +
    `environmentMessages=1`
);

node.status({
    fill:
        invalidWeightEvents > 0
            ? "yellow"
            : "green",

    shape: "dot",

    text:
        `${validWeightEvents} weights + 1 env`
});

// ============================================================================
// Send all generated messages through output 1
// ============================================================================
//
// With 18 valid weights, this sends 19 messages:
//
//   18 × Type 0x02 weight packets
//    1 × Type 0x01 environmental packet

node.send([outMessages]);

return null;

// ── FAI LoRaWAN Device Dispatcher v1.1 ─────────────────────────────────────
//
// Output 1: ShedSensor events, including up and join
// Output 2: Water-meter uplinks only
// Output 3: Water-meter joins and unknown devices/events

const payload =
    msg.payload || {};

const deviceInfo =
    payload.deviceInfo || {};

const tags =
    deviceInfo.tags &&
    typeof deviceInfo.tags === "object"
        ? deviceInfo.tags
        : {};

const profileName =
    String(
        deviceInfo.deviceProfileName || ""
    );

const eventType =
    String(msg.topic || "")
        .split("/")
        .filter(Boolean)
        .pop() || "unknown";

let deviceType =
    String(
        tags.sensor_type ||
        tags.device_type ||
        ""
    ).toLowerCase();

// Compatibility with existing profiles that do not yet have tags.
if (!deviceType) {
    if (profileName === "RAK3272 Node") {
        deviceType = "shed_sensor";
    } else if (
        profileName ===
        "B METERS HYDRODIGIT-S1 EU868"
    ) {
        deviceType = "water_meter";
    }
}

msg.fai = {
    deviceType,
    eventType,

    devEui:
        String(
            deviceInfo.devEui || ""
        ).toUpperCase(),

    deviceName:
        String(
            deviceInfo.deviceName || ""
        ),

    profileName,
    tags
};

// ShedSensor parser handles both uplinks and joins.
if (deviceType === "shed_sensor") {
    node.status({
        fill: "green",
        shape: "dot",
        text: `shed_sensor ${eventType}`
    });

    return [msg, null, null];
}

// Only water-meter uplinks contain application payload data.
if (
    deviceType === "water_meter" &&
    eventType === "up"
) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "water_meter up"
    });

    return [null, msg, null];
}

// Water-meter join events and unidentified devices go to diagnostics.
node.status({
    fill: "yellow",
    shape: "ring",
    text:
        `${deviceType || "unknown"} ${eventType}`
});

return [null, null, msg];

// ── FAI HYDRODIGIT LoRaWAN Raw Intake v1.0 ─────────────────────────────────
//
// Input:
//   ChirpStack /event/up message after the LoRaWAN dispatcher.
//
// Output:
//   A device-agnostic normalised raw LoRaWAN water-meter message.
//
// This node does not yet decode the proprietary HYDRODIGIT application
// payload. That section will be added once the payload specification or a
// real sample packet is available.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// Use a separate test topic until backend compatibility is confirmed.
const OUTPUT_TOPIC =
    `gateway/${gatewaySerial}/lorawan-watermeter/raw`;

// ============================================================================
// Validate ChirpStack message
// ============================================================================

const chirpstack =
    msg.payload || {};

const deviceInfo =
    chirpstack.deviceInfo || {};

if (
    !deviceInfo.devEui ||
    chirpstack.data === undefined ||
    chirpstack.data === null
) {
    node.warn(
        "Invalid HYDRODIGIT LoRaWAN message: " +
        "DevEUI or payload data is missing"
    );

    return null;
}

// ============================================================================
// Device metadata
// ============================================================================

const devEui =
    String(deviceInfo.devEui).toUpperCase();

const tags =
    deviceInfo.tags &&
    typeof deviceInfo.tags === "object"
        ? deviceInfo.tags
        : {};

const manufacturer =
    String(
        tags.manufacturer ||
        "B_METERS"
    );

const model =
    String(
        tags.model ||
        "HYDRODIGIT_S1"
    );

const meterSerial =
    String(
        tags.meter_serial ||
        tags.meterSerial ||
        deviceInfo.deviceName ||
        devEui
    );

const backendDeviceSerial =
    String(
        tags.backend_device_serial ||
        tags.backendDeviceSerial ||
        meterSerial
    );

// ============================================================================
// Decode raw LoRaWAN application payload
// ============================================================================

let rawBuffer;

try {
    if (Buffer.isBuffer(chirpstack.data)) {
        rawBuffer = chirpstack.data;
    } else {
        rawBuffer = Buffer.from(
            String(chirpstack.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode HYDRODIGIT payload from ${devEui}: ` +
        error.message
    );

    return null;
}

const rawBase64 =
    rawBuffer.toString("base64");

const rawHex =
    rawBuffer.toString("hex").toUpperCase();

// ============================================================================
// Radio metadata
// ============================================================================

let bestRssi = null;
let bestSnr = null;
let gatewayId = null;

if (
    Array.isArray(chirpstack.rxInfo) &&
    chirpstack.rxInfo.length > 0
) {
    const bestReception =
        chirpstack.rxInfo.reduce(
            (best, current) => {
                const currentRssi =
                    Number(current.rssi);

                const bestRssiValue =
                    Number(best.rssi);

                if (!Number.isFinite(bestRssiValue)) {
                    return current;
                }

                if (
                    Number.isFinite(currentRssi) &&
                    currentRssi > bestRssiValue
                ) {
                    return current;
                }

                return best;
            },
            chirpstack.rxInfo[0]
        );

    const candidateRssi =
        Number(bestReception.rssi);

    const candidateSnr =
        Number(bestReception.snr);

    bestRssi =
        Number.isFinite(candidateRssi)
            ? candidateRssi
            : null;

    bestSnr =
        Number.isFinite(candidateSnr)
            ? candidateSnr
            : null;

    gatewayId =
        bestReception.gatewayId || null;
}

// ============================================================================
// Timestamp
// ============================================================================

const receivedTimestamp =
    chirpstack.time ||
    new Date().toISOString();

// ============================================================================
// Normalised raw water-meter object
// ============================================================================

msg.waterMeter = {
    gatewaySerial,

    source: "lorawan",
    manufacturer,
    model,

    vendorDecoded:
        chirpstack.object &&
            typeof chirpstack.object === "object"
            ? chirpstack.object
            : null,

    devEui,
    meterSerial,
    backendDeviceSerial,

    timestamp: receivedTimestamp,

    lorawan: {
        applicationId:
            deviceInfo.applicationId || null,

        applicationName:
            deviceInfo.applicationName || null,

        deviceName:
            deviceInfo.deviceName || null,

        deviceProfileName:
            deviceInfo.deviceProfileName || null,

        devAddr:
            chirpstack.devAddr || null,

        frameCounter:
            Number.isInteger(
                Number(chirpstack.fCnt)
            )
                ? Number(chirpstack.fCnt)
                : null,

        fPort:
            Number.isInteger(
                Number(chirpstack.fPort)
            )
                ? Number(chirpstack.fPort)
                : null,

        confirmed:
            Boolean(chirpstack.confirmed),

        deduplicationId:
            chirpstack.deduplicationId || null
    },

    radio: {
        gatewayId,
        rssi: bestRssi,
        snr: bestSnr
    },

    raw: {
        base64: rawBase64,
        hex: rawHex,
        length: rawBuffer.length
    },

    // These fields will be populated by the actual HYDRODIGIT decoder.
    readings: {
        totalVolumeM3: null,
        intervalVolumeLitres: null,
        flowRateM3PerHour: null,
        waterTemperatureC: null
    },

    alarms: {
        leak: null,
        burst: null,
        reverseFlow: null,
        overflow: null,
        tamper: null,
        batteryLow: null
    }
};

// ============================================================================
// Temporary raw diagnostic output
// ============================================================================

msg.topic = OUTPUT_TOPIC;

msg.payload = {
    "_meta": {
        "received": receivedTimestamp,
        "receiver_id":
            gatewayId ||
            gatewaySerial,

        "rssi": bestRssi,
        "snr": bestSnr,
        "transport": "lorawan"
    },

    "data": {
        "DevEUI": devEui,
        "Manufacturer": manufacturer,
        "Model": model,
        "SerialNumber": meterSerial,
        "BackendDeviceSerial": backendDeviceSerial,
        "FPort": msg.waterMeter.lorawan.fPort,
        "FrameCounter":
            msg.waterMeter.lorawan.frameCounter,

        "PayloadLength":
            rawBuffer.length
    },

    "raw": rawBase64,
    "raw_hex": rawHex,
    "type": "lorawan_water_meter"
};

node.status({
    fill: "blue",
    shape: "dot",
    text:
        `${meterSerial}: ` +
        `${rawBuffer.length} bytes, ` +
        `port ${msg.waterMeter.lorawan.fPort}`
});

return msg;

// ── FAI HYDRODIGIT LoRaWAN Decoder v1.0 ─────────────────────────────────────
//
// Input:
//   msg.waterMeter from "HYDRODIGIT Raw Intake"
//
// Behaviour:
//   - Uses a ChirpStack decoded object when available.
//   - Preserves the original LoRaWAN payload.
//   - Produces a common water-meter structure.
//   - Does not fabricate readings when the payload format is unknown.
//
// Once the B METERS payload specification or a real packet is available,
// decodeHydrodigitRaw() can be completed without changing the rest of the flow.

// ============================================================================
// Validate input
// ============================================================================

if (
    !msg.waterMeter ||
    !msg.waterMeter.raw ||
    !msg.waterMeter.raw.base64
) {
    node.warn(
        "HYDRODIGIT Decoder: msg.waterMeter.raw is missing"
    );

    return null;
}

const meter = msg.waterMeter;

// ============================================================================
// Helpers
// ============================================================================

function getPath(object, path) {
    if (
        !object ||
        typeof object !== "object"
    ) {
        return undefined;
    }

    return path
        .split(".")
        .reduce(
            (value, key) =>
                value !== undefined &&
                value !== null
                    ? value[key]
                    : undefined,
            object
        );
}

function firstNumber(object, paths) {
    for (const path of paths) {
        const value =
            Number(getPath(object, path));

        if (Number.isFinite(value)) {
            return value;
        }
    }

    return null;
}

function firstBoolean(object, paths) {
    for (const path of paths) {
        const value =
            getPath(object, path);

        if (typeof value === "boolean") {
            return value;
        }

        if (
            value === 1 ||
            value === "1" ||
            String(value).toLowerCase() === "true"
        ) {
            return true;
        }

        if (
            value === 0 ||
            value === "0" ||
            String(value).toLowerCase() === "false"
        ) {
            return false;
        }
    }

    return null;
}

// ============================================================================
// Raw B METERS decoder placeholder
// ============================================================================
//
// Do not guess the HYDRODIGIT byte layout.
//
// This function will be replaced once we have:
//   - the B METERS LoRaWAN payload specification; or
//   - a real payload plus its confirmed decoded values.

function decodeHydrodigitRaw(
    rawBuffer,
    fPort
) {
    void rawBuffer;
    void fPort;

    return null;
}

// ============================================================================
// Obtain decoded data
// ============================================================================

let decoded = null;

if (
    meter.vendorDecoded &&
    typeof meter.vendorDecoded === "object" &&
    !Array.isArray(meter.vendorDecoded)
) {
    decoded = meter.vendorDecoded;
} else {
    let rawBuffer;

    try {
        rawBuffer =
            Buffer.from(
                meter.raw.base64,
                "base64"
            );
    } catch (error) {
        node.warn(
            "HYDRODIGIT Decoder: invalid Base64 payload — " +
            error.message
        );

        return null;
    }

    decoded =
        decodeHydrodigitRaw(
            rawBuffer,
            meter.lorawan
                ? meter.lorawan.fPort
                : null
        );
}

// ============================================================================
// No decoder available yet
// ============================================================================

if (
    !decoded ||
    typeof decoded !== "object"
) {
    meter.decodeStatus = "raw_only";
    meter.decodeError =
        "HYDRODIGIT payload specification not yet configured";

    node.status({
        fill: "yellow",
        shape: "ring",
        text:
            `${meter.meterSerial || meter.devEui}: raw only`
    });

    node.warn(
        `HYDRODIGIT raw packet captured — ` +
        `device=${meter.devEui}, ` +
        `port=${meter.lorawan?.fPort ?? "unknown"}, ` +
        `length=${meter.raw.length}, ` +
        `hex=${meter.raw.hex}`
    );

    return msg;
}

// ============================================================================
// Normalise decoded values
// ============================================================================

// Prefer explicitly named cubic-metre fields.
let totalVolumeM3 =
    firstNumber(
        decoded,
        [
            "totalVolumeM3",
            "total_volume_m3",
            "total_m3",
            "volume_total_m3",
            "meter.totalVolumeM3",
            "meter.total_volume_m3"
        ]
    );

// Alternatively accept an explicitly named litre total.
if (totalVolumeM3 === null) {
    const totalVolumeLitres =
        firstNumber(
            decoded,
            [
                "totalVolumeLitres",
                "total_volume_l",
                "total_litres",
                "volume_total_l",
                "meter.totalVolumeLitres"
            ]
        );

    if (totalVolumeLitres !== null) {
        totalVolumeM3 =
            totalVolumeLitres / 1000.0;
    }
}

const intervalVolumeLitres =
    firstNumber(
        decoded,
        [
            "intervalVolumeLitres",
            "interval_volume_l",
            "delta_volume_l",
            "consumption_litres",
            "meter.intervalVolumeLitres"
        ]
    );

const flowRateM3PerHour =
    firstNumber(
        decoded,
        [
            "flowRateM3PerHour",
            "flow_rate_m3h",
            "flow_m3_h",
            "meter.flowRateM3PerHour"
        ]
    );

const waterTemperatureC =
    firstNumber(
        decoded,
        [
            "waterTemperatureC",
            "water_temperature_c",
            "temperature_c",
            "meter.waterTemperatureC"
        ]
    );

// ============================================================================
// Store normalised result
// ============================================================================

meter.vendorDecoded = decoded;

meter.readings = {
    totalVolumeM3,
    intervalVolumeLitres,
    flowRateM3PerHour,
    waterTemperatureC
};

meter.alarms = {
    leak:
        firstBoolean(
            decoded,
            [
                "leak",
                "leak_alarm",
                "alarms.leak"
            ]
        ),

    burst:
        firstBoolean(
            decoded,
            [
                "burst",
                "burst_alarm",
                "alarms.burst"
            ]
        ),

    reverseFlow:
        firstBoolean(
            decoded,
            [
                "reverseFlow",
                "reverse_flow",
                "alarms.reverseFlow"
            ]
        ),

    overflow:
        firstBoolean(
            decoded,
            [
                "overflow",
                "overflow_alarm",
                "alarms.overflow"
            ]
        ),

    tamper:
        firstBoolean(
            decoded,
            [
                "tamper",
                "tamper_alarm",
                "alarms.tamper"
            ]
        ),

    batteryLow:
        firstBoolean(
            decoded,
            [
                "batteryLow",
                "battery_low",
                "alarms.batteryLow"
            ]
        )
};

meter.decodeStatus =
    Number.isFinite(totalVolumeM3)
        ? "decoded"
        : "partial";

meter.decodeError =
    meter.decodeStatus === "decoded"
        ? null
        : "Decoded object did not contain a recognised total-volume field";

node.status({
    fill:
        meter.decodeStatus === "decoded"
            ? "green"
            : "yellow",

    shape:
        meter.decodeStatus === "decoded"
            ? "dot"
            : "ring",

    text:
        `${meter.meterSerial || meter.devEui}: ` +
        meter.decodeStatus
});

return msg;

// ── FAI LoRaWAN Water Meter Backend Formatter v1.0 ──────────────────────────
//
// Input:
//   msg.waterMeter from the HYDRODIGIT decoder.
//
// Output envelope:
//   _meta
//   data
//   raw
//   type
//
// This matches the general structure of the existing wM-Bus message without
// falsely labelling a LoRaWAN payload as wM-Bus.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const OUTPUT_TOPIC =
    `gateway/${gatewaySerial}/watermeter/out`;

// ============================================================================
// Validate input
// ============================================================================

if (!msg.waterMeter) {
    node.warn(
        "Water Meter Formatter: msg.waterMeter is missing"
    );

    return null;
}

const meter =
    msg.waterMeter;

if (
    meter.decodeStatus !== "decoded" ||
    !meter.readings ||
    !Number.isFinite(
        Number(meter.readings.totalVolumeM3)
    )
) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "waiting for decoded volume"
    });

    node.warn(
        `Water meter not sent to backend — ` +
        `device=${meter.devEui || "unknown"}, ` +
        `decodeStatus=${meter.decodeStatus || "unknown"}`
    );

    return null;
}

// ============================================================================
// Helpers
// ============================================================================

function nullableNumber(value) {
    const number =
        Number(value);

    return Number.isFinite(number)
        ? number
        : null;
}

function nullableBoolean(value) {
    return typeof value === "boolean"
        ? value
        : null;
}

// ============================================================================
// Build backend message
// ============================================================================

const receivedTimestamp =
    meter.timestamp ||
    new Date().toISOString();

const receiverId =
    meter.radio &&
    meter.radio.gatewayId
        ? meter.radio.gatewayId
        : gatewaySerial;

const meterSerial =
    String(
        meter.meterSerial ||
        meter.devEui ||
        "UNKNOWN_METER"
    );

const backendDeviceSerial =
    String(
        meter.backendDeviceSerial ||
        meterSerial
    );

msg.topic =
    OUTPUT_TOPIC;

msg.payload = {
    "_meta": {
        "received": receivedTimestamp,
        "receiver_id": receiverId,
        "rssi":
            meter.radio
                ? nullableNumber(
                    meter.radio.rssi
                )
                : null,

        "snr":
            meter.radio
                ? nullableNumber(
                    meter.radio.snr
                )
                : null,

        "transport": "lorawan"
    },

    "data": {
        "ID": backendDeviceSerial,

        "Manufacturer":
            meter.manufacturer ||
            "B_METERS",

        "Model":
            meter.model ||
            "HYDRODIGIT_S1",

        "SerialNumber":
            meterSerial,

        "DevEUI":
            meter.devEui || null,

        "TotalVolumeM3":
            nullableNumber(
                meter.readings.totalVolumeM3
            ),

        "IntervalVolumeLitres":
            nullableNumber(
                meter.readings.intervalVolumeLitres
            ),

        "FlowRateM3PerHour":
            nullableNumber(
                meter.readings.flowRateM3PerHour
            ),

        "WaterTemperatureC":
            nullableNumber(
                meter.readings.waterTemperatureC
            ),

        "LeakAlarm":
            nullableBoolean(
                meter.alarms?.leak
            ),

        "BurstAlarm":
            nullableBoolean(
                meter.alarms?.burst
            ),

        "ReverseFlowAlarm":
            nullableBoolean(
                meter.alarms?.reverseFlow
            ),

        "OverflowAlarm":
            nullableBoolean(
                meter.alarms?.overflow
            ),

        "TamperAlarm":
            nullableBoolean(
                meter.alarms?.tamper
            ),

        "BatteryLow":
            nullableBoolean(
                meter.alarms?.batteryLow
            ),

        "FPort":
            meter.lorawan
                ? nullableNumber(
                    meter.lorawan.fPort
                )
                : null,

        "FrameCounter":
            meter.lorawan
                ? nullableNumber(
                    meter.lorawan.frameCounter
                )
                : null
    },

    "raw":
        meter.raw.base64,

    "type":
        "water_meter"
};

node.status({
    fill: "green",
    shape: "dot",
    text:
        `${meterSerial}: ` +
        `${meter.readings.totalVolumeM3} m³`
});

return msg;
